"""
Centralized Model Management Module for GGUF Models

This module provides centralized management for GGUF model lifecycle,
including initialization, validation, and configuration management.
"""

import os
import logging
from pathlib import Path
from typing import Optional, Dict, Any

from string_ai_coding_assistant.memos.log import get_logger

logger = get_logger(__name__)

try:
    from ctransformers import AutoModelForCausalLM, AutoConfig
    CTRANSFORMERS_AVAILABLE = True
except ImportError:
    logger.warning("ctransformers not available. Please install it: pip install ctransformers")
    CTRANSFORMERS_AVAILABLE = False


class GGUFModelManager:
    """
    Centralized manager for GGUF model lifecycle and configuration.
    
    This class handles model initialization, validation, and provides
    a clean interface for interacting with GGUF models through ctransformers.
    """
    
    def __init__(self, model_path: str, config: Optional[Dict[str, Any]] = None):
        """
        Initialize the GGUF Model Manager.
        
        Args:
            model_path (str): Path to the GGUF model file
            config (Optional[Dict[str, Any]]): Model configuration parameters
        """
        self.model_path = Path(model_path)
        self.config = config or {}
        self.model = None
        self._is_loaded = False
        
        # Default configuration
        self.default_config = {
            'max_new_tokens': 512,
            'temperature': 0.7,
            'top_p': 0.9,
            'top_k': 50,
            'repetition_penalty': 1.1,
            'gpu_layers': 0,  # CPU-only by default for compatibility
            'threads': os.cpu_count() or 4,
            'context_length': 16384,  # Increased from 2048 to better utilize model's training context
        }
        
        # Merge user config with defaults
        self.effective_config = {**self.default_config, **self.config}
        
        logger.info(f"Initialized GGUF Model Manager for: {self.model_path}")
    
    def validate_model_file(self) -> bool:
        """
        Validate that the model file exists and is accessible.
        
        Returns:
            bool: True if model file is valid, False otherwise
        """
        if not self.model_path.exists():
            logger.error(f"Model file not found: {self.model_path}")
            return False
            
        if not self.model_path.is_file():
            logger.error(f"Model path is not a file: {self.model_path}")
            return False
            
        if not self.model_path.suffix.lower() == '.gguf':
            logger.warning(f"Model file does not have .gguf extension: {self.model_path}")
            
        # Check file size (should be > 0)
        if self.model_path.stat().st_size == 0:
            logger.error(f"Model file is empty: {self.model_path}")
            return False
            
        logger.info(f"Model file validation successful: {self.model_path}")
        return True
    
    def load_model(self) -> bool:
        """
        Load the GGUF model using ctransformers.
        
        Returns:
            bool: True if model loaded successfully, False otherwise
        """
        if not CTRANSFORMERS_AVAILABLE:
            logger.error("ctransformers library is not available")
            return False
            
        if self._is_loaded:
            logger.info("Model already loaded")
            return True
            
        if not self.validate_model_file():
            return False
            
        try:
            logger.info(f"Loading GGUF model from: {self.model_path}")
            logger.info(f"Model configuration: {self.effective_config}")
            
            # Load model with configuration
            self.model = AutoModelForCausalLM.from_pretrained(
                str(self.model_path),
                model_type='auto',  # Auto-detect model type
                gpu_layers=self.effective_config['gpu_layers'],
                threads=self.effective_config['threads'],
                context_length=self.effective_config['context_length'],
            )
            
            self._is_loaded = True
            logger.info("GGUF model loaded successfully")
            return True
            
        except Exception as e:
            logger.error(f"Failed to load GGUF model: {e}")
            self.model = None
            self._is_loaded = False
            return False
    
    def unload_model(self) -> None:
        """
        Unload the model and free resources.
        """
        if self.model is not None:
            logger.info("Unloading GGUF model")
            self.model = None
            self._is_loaded = False
    
    def is_loaded(self) -> bool:
        """
        Check if the model is currently loaded.
        
        Returns:
            bool: True if model is loaded, False otherwise
        """
        return self._is_loaded and self.model is not None
    
    def generate(self, prompt: str, **kwargs) -> str:
        """
        Generate text using the loaded model.
        
        Args:
            prompt (str): Input prompt for generation
            **kwargs: Additional generation parameters
            
        Returns:
            str: Generated text
            
        Raises:
            RuntimeError: If model is not loaded
        """
        if not self.is_loaded():
            raise RuntimeError("Model is not loaded. Call load_model() first.")
        
        # Merge generation parameters
        gen_config = {**self.effective_config, **kwargs}
        
        try:
            logger.debug(f"Generating text for prompt: {prompt[:100]}...")
            
            response = self.model(
                prompt,
                max_new_tokens=gen_config['max_new_tokens'],
                temperature=gen_config['temperature'],
                top_p=gen_config['top_p'],
                top_k=gen_config['top_k'],
                repetition_penalty=gen_config['repetition_penalty'],
            )
            
            logger.debug(f"Generated response: {response[:100]}...")
            return response
            
        except Exception as e:
            logger.error(f"Error during text generation: {e}")
            raise
    
    def get_model_info(self) -> Dict[str, Any]:
        """
        Get information about the loaded model.
        
        Returns:
            Dict[str, Any]: Model information including path, config, and status
        """
        return {
            'model_path': str(self.model_path),
            'is_loaded': self.is_loaded(),
            'config': self.effective_config,
            'model_size_mb': round(self.model_path.stat().st_size / (1024 * 1024), 2) if self.model_path.exists() else None,
            'ctransformers_available': CTRANSFORMERS_AVAILABLE,
        }


def create_model_manager(model_path: str, config: Optional[Dict[str, Any]] = None) -> GGUFModelManager:
    """
    Factory function to create a GGUF Model Manager instance.
    
    Args:
        model_path (str): Path to the GGUF model file
        config (Optional[Dict[str, Any]]): Model configuration parameters
        
    Returns:
        GGUFModelManager: Configured model manager instance
    """
    return GGUFModelManager(model_path, config) 